<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\RelyingParty\Domain;

use Civi\Lughauth\Features\Access\RelyingParty\Domain\ValueObject\Holder\RelyingPartyUidAttributeHolder;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\ValueObject\Holder\RelyingPartyCodeAttributeHolder;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\ValueObject\Holder\RelyingPartyApiKeyAttributeHolder;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\ValueObject\Holder\RelyingPartyEnabledAttributeHolder;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\ValueObject\Holder\RelyingPartyVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class RelyingPartyAttributes
{
    use RelyingPartyUidAttributeHolder;
    use RelyingPartyCodeAttributeHolder;
    use RelyingPartyApiKeyAttributeHolder;
    use RelyingPartyEnabledAttributeHolder;
    use RelyingPartyVersionAttributeHolder;

    private const array UNSETS = [
      'uid' => 'unsetUid',
      'code' => 'unsetCode',
      'apiKey' => 'unsetApiKey',
      'enabled' => 'unsetEnabled',
      'version' => 'unsetVersion',
    ];

    public function createNewInstance(): RelyingParty
    {
        $errors = new ConstraintFailList();
        $uid = $this->uidTryBuildInitial($errors);
        $code = $this->codeTryBuildInitial($errors);
        $apiKey = $this->apiKeyTryBuildInitial($errors);
        $enabled = $this->enabledTryBuildInitial($errors);
        $version = $this->versionTryBuildInitial($errors);
        if ($errors->hasErrors()) {
            throw $errors->asConstraintException();
        }
        \assert($uid !== null);
        \assert($code !== null);
        \assert($apiKey !== null);
        return new RelyingParty(
            uid: $uid,
            code: $code,
            apiKey: $apiKey,
            enabled: $enabled,
            version: $version,
        );
    }
    public function withAssertedRules(): RelyingPartyAttributes
    {
        $value = new RelyingPartyAttributes();
        $errorsList = new ConstraintFailList();
        $this->withAssertedUidRules($value, $errorsList);
        $this->withAssertedCodeRules($value, $errorsList);
        $this->withAssertedApiKeyRules($value, $errorsList);
        $this->withAssertedEnabledRules($value, $errorsList);
        $this->withAssertedVersionRules($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        return $value;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): RelyingPartyAttributes
    {
        $this->withDefaultUid();
        $this->withDefaultCode();
        $this->withDefaultApiKey();
        $this->withDefaultEnabled();
        $this->withDefaultVersion();
        return $this;
    }
}
